//  The runtime implementing Core.clmodule for code generated by CodeGen. The
//  layout and calling convention are described in
//  Sources/CodeGen/Runtime/RuntimeABI.swift.
//

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <stdbool.h>

// ============ Layout ============

typedef struct Object Object;

// Every vtable starts with this header, followed by the method slots.
// The generated code defines the vtables, the runtime only reads them.
typedef struct VTable {
    const struct VTable* parent;
    const char* type_name;
    int64_t size;
    Object* (*new)(void);
    void* methods[];
} VTable;

struct Object {
    const VTable* vtable;
};

typedef struct {
    Object base;
} IO;

typedef struct {
    Object base;
    int32_t value;
} Int;

typedef struct {
    Object base;
    bool value;
} Bool;

typedef struct {
    Object base;
    char* value;
} String;

extern const VTable Int_vtable_instance;
extern const VTable Bool_vtable_instance;
extern const VTable String_vtable_instance;

static void* cool_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Out of memory\n");
        exit(1);
    }
    return ptr;
}

// ============ Boxing ============

Int* Int_new(int32_t value) {
    Int* self = cool_malloc(sizeof(Int));
    self->base.vtable = &Int_vtable_instance;
    self->value = value;
    return self;
}

Bool* Bool_new(bool value) {
    Bool* self = cool_malloc(sizeof(Bool));
    self->base.vtable = &Bool_vtable_instance;
    self->value = value;
    return self;
}

String* String_new(char* value) {
    String* self = cool_malloc(sizeof(String));
    self->base.vtable = &String_vtable_instance;
    self->value = value;
    return self;
}

// ============ Object ============

Object* Object_abort(Object* self) {
    fprintf(stderr, "Abort called from class %s\n", self->vtable->type_name);
    exit(1);
}

String* Object_type_name(Object* self) {
    return String_new((char*)self->vtable->type_name);
}

Object* Object_copy(Object* self) {
    size_t size = self->vtable->size;
    Object* copy = cool_malloc(size);
    memcpy(copy, self, size);
    return copy;
}

// ============ IO ============

IO* IO_out_string(IO* self, String* string) {
    printf("%s", string->value);
    fflush(stdout);
    return self;
}

IO* IO_out_int(IO* self, Int* integer) {
    printf("%d", integer->value);
    fflush(stdout);
    return self;
}

String* IO_in_string(IO* self) {
    char* buffer = cool_malloc(1025);
    if (!fgets(buffer, 1025, stdin)) {
        buffer[0] = '\0';
    }
    size_t len = strlen(buffer);
    if (len > 0 && buffer[len - 1] == '\n') {
        buffer[len - 1] = '\0';
    }
    return String_new(buffer);
}

Int* IO_in_int(IO* self) {
    String* line = IO_in_string(self);
    return Int_new((int32_t)strtol(line->value, NULL, 10));
}

// ============ String ============

Int* String_length(String* self) {
    return Int_new((int32_t)strlen(self->value));
}

String* String_concat(String* self, String* other) {
    size_t len1 = strlen(self->value);
    size_t len2 = strlen(other->value);

    char* result = cool_malloc(len1 + len2 + 1);
    memcpy(result, self->value, len1);
    memcpy(result + len1, other->value, len2 + 1);
    return String_new(result);
}

String* String_substr(String* self, Int* start, Int* length) {
    int32_t len = (int32_t)strlen(self->value);
    int32_t start_int = start->value;
    int32_t length_int = length->value;

    if (start_int < 0 || length_int < 0 || start_int + length_int > len) {
        fprintf(stderr, "String.substr out of range\n");
        exit(1);
    }

    char* result = cool_malloc(length_int + 1);
    memcpy(result, self->value + start_int, length_int);
    result[length_int] = '\0';
    return String_new(result);
}
